  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
  }

  const rl = await authedRatelimit.limit(auth.user.id)
  if (!rl.success) {
    return NextResponse.json({ error: 'Too many requests.' }, { status: 429 })
  }

  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'Owner role required.' }, { status: 403 })
  }

  const supabase = createServiceRoleClient()

  try {
    // §S13.3 — nec_1099_exports not yet in generated types; untyped cast.
    const fromUntyped = supabase.from.bind(supabase) as unknown as (
      table: string,
    ) => ReturnType<typeof supabase.from>

    const { data: exportsRaw, error } = await fromUntyped('nec_1099_exports')
      .select('id, year, artist_id, total_paid_cents, nec_threshold_met, source, generated_at, csv_url')
      .eq('studio_id', auth.studioId)
      .order('year', { ascending: false })
      .order('total_paid_cents', { ascending: false })

    if (error) {
      logger.error({ err: error, studioId: auth.studioId }, 'tax-documents GET: query failed')
      return NextResponse.json({ error: 'Could not load tax documents.' }, { status: 500 })
    }

    const exports_ = (exportsRaw ?? []) as Array<{
      id: string
      year: number
      artist_id: string
      total_paid_cents: number
      nec_threshold_met: boolean | null
      source: string
      generated_at: string
      csv_url: string | null
    }>

    // Resolve artist display names
    const artistIds = [...new Set(exports_.map((e) => e.artist_id))]
    let artistNameMap: Record<string, string> = {}
    if (artistIds.length > 0) {
      const { data: artistData } = await fromUntyped('artists')
        .select('id, display_name')
        .in('id', artistIds)
      const artistRows = (artistData ?? []) as Array<{ id: string; display_name: string | null }>
      for (const a of artistRows) {
        artistNameMap[a.id] = a.display_name ?? 'Unknown Artist'
      }
    }

    const exportsList = exports_.map((e) => ({
      ...e,
      artist_name: artistNameMap[e.artist_id] ?? 'Unknown Artist',
    }))

    return NextResponse.json({ exports: exportsList })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'tax-documents GET: unexpected error')
    return NextResponse.json({ error: 'Could not load tax documents.' }, { status: 500 })
  }
}

